public class Main {
    static final class Contador {
        private final Object candado = new Object();
        private int minutos;
        void sumar(int extra) {
            synchronized (candado) { minutos += extra; }
        }
        int total() {
            synchronized (candado) { return minutos; }
        }
    }

    public static void main(String[] args) {
        Contador diario = new Contador();
        diario.sumar(25);
        System.out.println(diario.total());
    }
}

